def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]]
    # Determine whether the colored stripes run along r+c or r-c.
    sums = {}
    diffs = {}
    for r, c, v in points:
        sums.setdefault(r + c, set()).add(v)
        diffs.setdefault(r - c, set()).add(v)
    # All clues on a stripe share the same diagonal index and color.
    # Use the diagonal orientation containing the most repeated clues.
    sscore = max((len(v) for v in sums.values()), default=0)
    dscore = max((len(v) for v in diffs.values()), default=0)
    use_sum = sscore >= dscore
    key = (lambda r, c: r + c) if use_sum else (lambda r, c: r - c)

    known = {}
    for r, c, v in points:
        known[key(r, c)] = v

    # Continue the periodic stripe sequence, using the smallest period
    # consistent with all observed stripe colors.
    ks = sorted(known)
    period = max(1, ks[-1] - ks[0] + 1)
    for p in range(1, period + 1):
        if all(known[a] == known[b] for a in ks for b in ks
               if (a - ks[0]) % p == (b - ks[0]) % p):
            period = p
            break

    residues = {}
    for k, v in known.items():
        residues[(k - ks[0]) % period] = v

    # Fill any unobserved positions in the cycle by extending the
    # ordered sequence of stripe colors.
    ordered = [known[k] for k in ks]
    for i in range(period):
        residues.setdefault(i, ordered[i % len(ordered)])

    return [[residues[(key(r, c) - ks[0]) % period] for c in range(w)]
            for r in range(h)]
